<template>
  <div class="user-page">
    <div class="back-home">
      <el-button type="primary" @click="goToHome">返回首页</el-button>
    </div>
    <h1 class="page-title">用户中心</h1>
    <p class="welcome-message">欢迎回来，{{ userNickname }}</p>

    <div class="user-info card">
      <h2>个人信息</h2>
      <img
        v-if="userAvatar"
        :src="userAvatar"
        alt="用户头像"
        class="user-avatar"
      />
      <ul>
        <li>昵称：{{ userNickname }}</li>
        <li>手机：{{ userPhone }}</li>
        <li>地址：{{ userAddress }}</li>
        <li>
          账户余额：¥{{ userBalance.toFixed(2) }}
          <span class="balance-warning"
            >（账户余额变更后需要退出账号重新登录才能刷新）</span
          >
        </li>
      </ul>
    </div>

    <div class="user-actions">
      <El-button type="primary" @click="showEditDialog" class="action-button"
        >编辑资料</El-button
      >
      <El-button type="success" @click="showPostDialog" class="action-button"
        >发表帖子</El-button
      >
      <El-button type="info" @click="showSecurityDialog" class="action-button"
        >设置密保</El-button
      >
      <El-button type="danger" @click="logout" class="action-button"
        >注销登录</El-button
      >
    </div>

    <!-- 编辑资料对话框 -->
    <El-dialog
      v-model="editDialogVisible"
      title="编辑资料"
      width="500px"
      :close-on-click-modal="false"
    >
      <El-form :model="editForm" label-width="80px">
        <El-form-item label="头像">
          <div class="avatar-upload">
            <img
              v-if="editForm.avatar"
              :src="editForm.avatar"
              class="avatar-preview"
              alt="用户头像"
            />
            <El-upload
              class="avatar-uploader"
              action="http://www.groupbuyingsystem.site/api/user/upload-avatar"
              :show-file-list="false"
              :on-success="handleAvatarSuccess"
              :before-upload="beforeAvatarUpload"
              :headers="uploadHeaders"
              :with-credentials="true"
            >
              <El-button type="primary">上传头像</El-button>
            </El-upload>
          </div>
        </El-form-item>

        <El-form-item label="昵称">
          <El-input v-model="editForm.nickname" placeholder="请输入昵称" />
        </El-form-item>

        <El-form-item label="手机">
          <El-input v-model="editForm.phone" placeholder="请输入手机号码" />
        </El-form-item>

        <El-form-item label="地址">
          <El-input v-model="editForm.address" placeholder="请输入地址" />
        </El-form-item>
      </El-form>
      <template #footer>
        <span class="dialog-footer">
          <El-button @click="editDialogVisible = false">取消</El-button>
          <El-button type="primary" @click="saveProfile">保存</El-button>
        </span>
      </template>
    </El-dialog>

    <!-- 发表帖子对话框 -->
    <El-dialog
      v-model="postDialogVisible"
      title="发表帖子"
      width="500px"
      :close-on-click-modal="false"
    >
      <El-form :model="postForm" label-width="80px">
        <El-form-item label="内容">
          <El-input
            v-model="postForm.content"
            type="textarea"
            :rows="4"
            placeholder="写下你想分享的内容..."
          />
        </El-form-item>
      </El-form>
      <template #footer>
        <span class="dialog-footer">
          <El-button @click="postDialogVisible = false">取消</El-button>
          <El-button type="primary" @click="submitPost">发表</El-button>
        </span>
      </template>
    </El-dialog>

    <!-- 设置密保对话框 -->
    <El-dialog
      v-model="securityDialogVisible"
      title="设置密保"
      width="500px"
      :close-on-click-modal="false"
    >
      <El-form
        ref="securityFormRef"
        :model="securityForm"
        :rules="securityRules"
        label-width="100px"
      >
        <El-form-item label="密保问题" prop="question">
          <El-select
            v-model="securityForm.question"
            placeholder="请选择密保问题"
          >
            <El-option label="您的出生地是？" value="您的出生地是？" />
            <El-option label="您的母亲姓名是？" value="您的母亲姓名是？" />
            <El-option label="您的小学校名是？" value="您的小学校名是？" />
            <El-option label="您的宠物名字是？" value="您的宠物名字是？" />
            <El-option label="您最喜欢的颜色是？" value="您最喜欢的颜色是？" />
          </El-select>
        </El-form-item>
        <El-form-item label="密保答案" prop="answer">
          <El-input
            v-model="securityForm.answer"
            type="text"
            placeholder="请输入密保答案"
          />
        </El-form-item>
      </El-form>
      <template #footer>
        <El-button @click="securityDialogVisible = false">取消</El-button>
        <El-button type="primary" @click="submitSecurityForm">确认</El-button>
      </template>
    </El-dialog>

    <div class="user-community card">
      <h2>社区互动</h2>
      <div v-if="posts.length === 0">暂无帖子。</div>
      <div v-else class="post-list">
        <div v-for="post in posts" :key="post.id" class="post-item">
          <div class="post-header">
            <img
              v-if="post.userAvatar"
              :src="`${API_BASE_URL}${post.userAvatar}`"
              alt="用户头像"
              class="post-user-avatar"
            />
            <span class="post-username">{{ post.username }}</span>
            <span class="post-time">{{ formatDate(post.createdAt) }}</span>
          </div>
          <div class="post-content">{{ post.content }}</div>
          <div class="post-actions">
            <el-button
              @click="toggleLike(post.id)"
              class="like-button"
              :type="post.liked ? 'primary' : 'default'"
            >
              <i class="el-icon-star-off"></i>
              {{ post.likes }} 赞
            </el-button>
            <el-button
              @click="showCommentInput(post.id)"
              class="comment-button"
              type="text"
            >
              <i class="el-icon-chat-dot-round"></i>
              评论
            </el-button>
            <el-button
              v-if="post.userId === userId"
              @click="deletePost(post.id)"
              class="delete-button"
              type="danger"
              text
            >
              <i class="el-icon-delete"></i>
              删除
            </el-button>
          </div>
          <!-- 评论输入框 -->
          <div class="comment-section" v-if="post.showCommentInput">
            <el-input
              v-model="newComment"
              type="textarea"
              :rows="2"
              placeholder="写下你的评论..."
            />
            <el-button
              type="primary"
              @click="submitComment(post.id)"
              class="submit-comment"
            >
              提交评论
            </el-button>
          </div>
          <!-- 评论列表 -->
          <div
            class="comments-list"
            v-if="post.comments && post.comments.length"
          >
            <div
              v-for="comment in post.comments"
              :key="comment.id"
              class="comment-item"
            >
              <div class="comment-header">
                <img
                  v-if="comment.userAvatar"
                  :src="`${API_BASE_URL}${comment.userAvatar}`"
                  alt="用户头像"
                  class="comment-user-avatar"
                />
                <span class="comment-username">{{ comment.username }}</span>
                <span class="comment-time">{{
                  formatDate(comment.createdAt)
                }}</span>
              </div>
              <div class="comment-content">{{ comment.content }}</div>
              <div class="comment-actions">
                <el-button
                  type="text"
                  @click="showReplyInput(post.id, comment.id)"
                >
                  <i class="el-icon-chat-dot-round"></i> 回复
                </el-button>
                <el-button
                  v-if="comment.replyCount > 0"
                  type="text"
                  @click="toggleReplies(comment)"
                >
                  <i
                    :class="
                      comment.showReplies
                        ? 'el-icon-arrow-up'
                        : 'el-icon-arrow-down'
                    "
                  ></i>
                  {{
                    comment.showReplies
                      ? "收起回复"
                      : `查看回复(${comment.replyCount})`
                  }}
                </el-button>
              </div>
              <!-- 回复输入框 -->
              <div class="reply-input" v-if="comment.showReplyInput">
                <el-input
                  v-model="comment.replyContent"
                  type="textarea"
                  :rows="2"
                  placeholder="写下你的回复..."
                />
                <div class="reply-actions">
                  <el-button @click="cancelReply(comment)">取消</el-button>
                  <el-button
                    type="primary"
                    @click="
                      submitReply(post.id, comment.id, comment.replyContent)
                    "
                  >
                    提交回复
                  </el-button>
                </div>
              </div>
              <!-- 子回复列表 -->
              <div
                class="replies-list"
                v-if="
                  comment.showReplies &&
                  comment.replies &&
                  comment.replies.length > 0
                "
              >
                <div
                  v-for="reply in comment.replies"
                  :key="reply.id"
                  class="reply-item"
                >
                  <div class="reply-header">
                    <img
                      v-if="reply.userAvatar"
                      :src="`${API_BASE_URL}${reply.userAvatar}`"
                      alt="用户头像"
                      class="reply-user-avatar"
                    />
                    <span class="reply-username">{{ reply.username }}</span>
                    <span class="reply-time">{{
                      formatDate(reply.createdAt)
                    }}</span>
                  </div>
                  <div class="reply-content">{{ reply.content }}</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { computed, ref, onMounted } from "vue";
import { useStore } from "vuex";
import { useRouter } from "vue-router";
import { ElMessage } from "element-plus";
import axios from "axios";

const store = useStore();
const router = useRouter();

// API基础URL
const API_BASE_URL = "http://www.groupbuyingsystem.site";

// 获取当前用户ID
const userId = computed(() => store.getters.userId);

// 编辑对话框相关
const editDialogVisible = ref(false);
const editForm = ref({
  avatar: "",
  nickname: "",
  phone: "",
  address: "",
});

// 上传头像相关
const uploadHeaders = computed(() => {
  const token = localStorage.getItem("token");
  return {
    Authorization: `Bearer ${token}`,
  };
});

// 头像上传前的验证
const beforeAvatarUpload = (file) => {
  const isImage = file.type.startsWith("image/");
  const isLt2M = file.size / 1024 / 1024 < 2;

  if (!isImage) {
    ElMessage.error("上传头像图片只能是图片格式!");
    return false;
  }
  if (!isLt2M) {
    ElMessage.error("上传头像图片大小不能超过 2MB!");
    return false;
  }
  return true;
};

// 头像上传成功处理
const handleAvatarSuccess = (response) => {
  if (response.code === 200) {
    editForm.value.avatar = response.data;
    store.commit("setUserAvatar", response.data);
    ElMessage.success("头像上传成功");
  } else {
    ElMessage.error("头像上传失败：" + response.message);
  }
};

// 计算用户信息
const userNickname = computed(() => store.getters.userNickname);
const userPhone = computed(() => store.getters.userPhoneNumber || "未提供");
const userAddress = computed(() => store.getters.userAddress || "未提供");
const userBalance = computed(() => store.getters.userBalance || 0);
const userAvatar = computed(() => {
  const avatar = store.getters.userAvatar;
  if (!avatar) {
    return "/assets/avatar.png";
  }
  if (avatar.startsWith("/assets/")) {
    return avatar;
  }
  return `${API_BASE_URL}${avatar}`;
});

// 在组件挂载时获取账户余额
onMounted(async () => {
  await store.getters.userBalance;
  await fetchUserInfo();
});

// 显示编辑对话框
const showEditDialog = () => {
  editForm.value = {
    avatar: userAvatar.value,
    nickname: userNickname.value,
    phone: userPhone.value,
    address: userAddress.value,
  };
  editDialogVisible.value = true;
};

// 保存资料
const saveProfile = async () => {
  try {
    await store.dispatch("updateUserProfile", {
      avatar: editForm.value.avatar,
      nickname: editForm.value.nickname,
      phone: editForm.value.phone,
      address: editForm.value.address,
    });
    ElMessage.success("资料更新成功");
    editDialogVisible.value = false;
  } catch (error) {
    ElMessage.error("资料更新失败：" + error.message);
  }
};

const logout = () => {
  store.commit("clearUser");
  router.push({ name: "Login" });
};

const goToHome = () => {
  router.push("/");
};

const userInfo = ref({});
const posts = ref([]);
const newComment = ref("");
const loading = ref(false);

// 获取用户信息
const fetchUserInfo = async () => {
  if (!userId.value) {
    ElMessage.error("用户未登录");
    return;
  }

  try {
    const response = await axios.get(`${API_BASE_URL}/api/user/profile`, {
      headers: {
        Authorization: `Bearer ${localStorage.getItem("token")}`,
      },
    });
    userInfo.value = response.data;
  } catch (error) {
    console.error("获取用户信息失败:", error);
    if (error.response?.status === 401) {
      ElMessage.error("登录已过期，请重新登录");
      router.push("/login");
    } else {
      ElMessage.error("获取用户信息失败");
    }
  }
};

// 获取所有帖子
const fetchAllPosts = async () => {
  try {
    loading.value = true;
    const response = await axios.get(`${API_BASE_URL}/api/posts/all`, {
      params: {
        page: Number(0),
        size: Number(10),
        sortBy: "createdAt",
        direction: "DESC",
      },
      headers: {
        Authorization: `Bearer ${localStorage.getItem("token")}`,
      },
      paramsSerializer: (params) => {
        return Object.entries(params)
          .map(([key, value]) => `${key}=${encodeURIComponent(value)}`)
          .join("&");
      },
    });
    if (response.data.code === 200 && response.data.data) {
      posts.value = response.data.data.content.map((post) => ({
        ...post,
        showCommentInput: false,
        liked: post.liked || false,
      }));
    } else {
      posts.value = [];
    }
  } catch (error) {
    console.error("获取帖子列表失败:", error);
    if (error.response?.status === 401) {
      ElMessage.error("登录已过期，请重新登录");
      router.push("/login");
    } else if (error.response?.data?.message) {
      ElMessage.error(error.response.data.message);
    } else {
      ElMessage.error("获取帖子列表失败");
    }
  } finally {
    loading.value = false;
  }
};

// 显示评论输入框
const showCommentInput = (postId) => {
  posts.value = posts.value.map((post) => ({
    ...post,
    showCommentInput: post.id === postId,
    showReplyInput: false, // 关闭所有回复输入框
  }));
};

// 提交评论
const submitComment = async (postId) => {
  if (!newComment.value.trim()) {
    ElMessage.warning("评论内容不能为空");
    return;
  }

  try {
    console.log("发送评论请求:", {
      postId,
      content: newComment.value.trim(),
    });

    const response = await axios.post(
      `${API_BASE_URL}/api/posts/${postId}/comments`,
      {
        content: newComment.value.trim(),
      },
      {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
          "Content-Type": "application/json",
        },
      },
    );

    console.log("评论响应:", response.data);

    if (response.data.code === 200) {
      ElMessage.success("评论成功");
      newComment.value = "";
      // 关闭评论输入框
      posts.value = posts.value.map((post) => ({
        ...post,
        showCommentInput: false,
      }));
      // 重新获取帖子列表以更新评论
      await fetchAllPosts();
    } else {
      ElMessage.error(response.data.message || "评论失败");
    }
  } catch (error) {
    console.error("评论失败:", error);
    if (error.response?.status === 401) {
      ElMessage.error("登录已过期，请重新登录");
      router.push("/login");
    } else {
      ElMessage.error(error.response?.data?.message || "评论失败");
    }
  }
};

// 点赞/取消点赞
const toggleLike = async (postId) => {
  try {
    const response = await axios.post(
      `${API_BASE_URL}/api/posts/${postId}/like`,
      {},
      {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
        },
      },
    );
    if (response.data.code === 200) {
      // 更新帖子的点赞状态
      posts.value = posts.value.map((post) => {
        if (post.id === postId) {
          return {
            ...post,
            likes: post.liked ? post.likes - 1 : post.likes + 1,
            liked: !post.liked,
          };
        }
        return post;
      });
      ElMessage.success(response.data.message || "操作成功");
    }
  } catch (error) {
    console.error("点赞操作失败:", error);
    if (error.response?.status === 401) {
      ElMessage.error("登录已过期，请重新登录");
      router.push("/login");
    } else {
      ElMessage.error("操作失败");
    }
  }
};

// 格式化日期
const formatDate = (date) => {
  return new Date(date).toLocaleString();
};

// 发表帖子相关
const postDialogVisible = ref(false);
const postForm = ref({
  content: "",
});

// 显示发表帖子对话框
const showPostDialog = () => {
  postForm.value.content = "";
  postDialogVisible.value = true;
};

// 提交帖子
const submitPost = async () => {
  if (!postForm.value.content.trim()) {
    ElMessage.warning("帖子内容不能为空");
    return;
  }

  try {
    const response = await axios.post(
      `${API_BASE_URL}/api/posts`,
      {
        content: postForm.value.content.trim(),
        userId: userId.value,
      },
      {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
          "Content-Type": "application/json",
        },
      },
    );

    if (response.data.code === 200) {
      ElMessage.success("帖子发表成功");
      postDialogVisible.value = false;
      await fetchAllPosts();
    } else {
      ElMessage.error(response.data.message || "发表帖子失败");
    }
  } catch (error) {
    console.error("发表帖子失败:", error);
    if (error.response?.status === 401) {
      ElMessage.error("登录已过期，请重新登录");
      router.push("/login");
    } else if (error.response?.data?.message) {
      ElMessage.error(error.response.data.message);
    } else {
      ElMessage.error("发表帖子失败");
    }
  }
};

// 显示回复输入框
const showReplyInput = (postId, commentId, replyToId = null) => {
  posts.value = posts.value.map((post) => {
    if (post.id === postId) {
      post.comments = post.comments.map((comment) => {
        if (comment.id === commentId) {
          return {
            ...comment,
            showReplyInput: true,
            replyContent: "",
            replyToId,
          };
        }
        return {
          ...comment,
          showReplyInput: false,
        };
      });
    }
    return post;
  });
};

// 取消回复
const cancelReply = (comment) => {
  comment.showReplyInput = false;
  comment.replyContent = "";
};

// 切换显示回复
const toggleReplies = async (comment) => {
  try {
    // 如果已经显示回复，则隐藏
    if (comment.showReplies) {
      comment.showReplies = false;
      return;
    }

    // 如果还没有加载回复，则从服务器获取
    if (!comment.replies || comment.replies.length === 0) {
      const response = await axios.get(
        `${API_BASE_URL}/api/posts/comments/${comment.id}/replies`,
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        },
      );

      if (response.data.code === 200) {
        comment.replies = response.data.data;
        console.log("获取到的回复:", comment.replies); // 添加调试日志
      } else {
        ElMessage.error(response.data.message || "获取回复失败");
        return;
      }
    }

    comment.showReplies = true;
  } catch (error) {
    console.error("获取回复失败:", error);
    ElMessage.error("获取回复失败");
  }
};

// 提交回复
const submitReply = async (postId, commentId, content, replyToId = null) => {
  if (!content || !content.trim()) {
    ElMessage.warning("回复内容不能为空");
    return;
  }

  try {
    const response = await axios.post(
      `${API_BASE_URL}/api/posts/comments/${commentId}/reply`,
      {
        content: content.trim(),
        postId,
        parentId: commentId,
        replyToId,
      },
      {
        headers: {
          Authorization: `Bearer ${localStorage.getItem("token")}`,
          "Content-Type": "application/json",
        },
      },
    );

    if (response.data.code === 200) {
      ElMessage.success("回复成功");
      // 更新评论列表
      await fetchAllPosts();
    } else {
      ElMessage.error(response.data.message || "回复失败");
    }
  } catch (error) {
    console.error("回复失败:", error);
    if (error.response?.status === 401) {
      ElMessage.error("登录已过期，请重新登录");
      router.push("/login");
    } else {
      ElMessage.error("回复失败");
    }
  }
};

// 删除帖子
const deletePost = async (postId) => {
  try {
    const response = await axios.delete(`${API_BASE_URL}/api/posts/${postId}`, {
      headers: {
        Authorization: `Bearer ${localStorage.getItem("token")}`,
      },
    });

    if (response.data.code === 200) {
      ElMessage.success("帖子删除成功");
      // 从列表中移除已删除的帖子
      posts.value = posts.value.filter((post) => post.id !== postId);
    }
  } catch (error) {
    console.error("删除帖子失败:", error);
    if (error.response?.status === 401) {
      ElMessage.error("登录已过期，请重新登录");
      router.push("/login");
    } else if (error.response?.status === 403) {
      ElMessage.error("您没有权限删除此帖子");
    } else {
      ElMessage.error(error.response?.data?.message || "删除帖子失败");
    }
  }
};

// 密保相关
const securityDialogVisible = ref(false);
const securityFormRef = ref(null);
const securityForm = ref({
  question: "",
  answer: "",
});

const securityRules = {
  question: [{ required: true, message: "请选择密保问题", trigger: "change" }],
  answer: [
    { required: true, message: "请输入密保答案", trigger: "blur" },
    { min: 2, message: "答案长度至少2个字符", trigger: "blur" },
  ],
};

const showSecurityDialog = () => {
  securityForm.value = {
    question: "",
    answer: "",
  };
  securityDialogVisible.value = true;
};

const submitSecurityForm = async () => {
  if (!securityFormRef.value) return;

  await securityFormRef.value.validate(async (valid) => {
    if (valid) {
      try {
        const response = await axios.post(
          `${API_BASE_URL}/api/user/security-question`,
          securityForm.value,
          {
            headers: {
              Authorization: `Bearer ${localStorage.getItem("token")}`,
            },
          },
        );

        if (response.data.code === 200) {
          ElMessage.success("密保设置成功");
          securityDialogVisible.value = false;
        } else {
          ElMessage.error(response.data.message || "设置失败");
        }
      } catch (error) {
        console.error("设置密保失败:", error);
        ElMessage.error("设置密保失败，请重试");
      }
    }
  });
};

onMounted(() => {
  fetchUserInfo();
  fetchAllPosts();
});
</script>

